#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
void sgf_free(sgf_tree *t) {
    if (!t)
        return;
    for (size_t i = 0; i < t->property_count; i++) {
        free(t->properties[i].key);
        for (size_t j = 0; j < t->properties[i].count; j++)
            free(t->properties[i].values[j]);
        free(t->properties[i].values);
    }
    for (size_t i = 0; i < t->child_count; i++)
        sgf_free(t->children[i]);
    free(t->properties);
    free(t->children);
    free(t);
}
static void child(sgf_tree *t, sgf_tree *c) {
    t->children =
        (sgf_tree **)realloc(t->children, (t->child_count + 1) * sizeof(sgf_tree *));
    t->children[t->child_count++] = c;
}
static sgf_tree *sequence(const char **p, bool *ok);
static sgf_tree *node(const char **p, bool *ok) {
    if (**p != ';') {
        *ok = false;
        return NULL;
    }
    (*p)++;
    sgf_tree *t = (sgf_tree *)calloc(1, sizeof(sgf_tree));
    while (**p && **p != ';' && **p != '(' && **p != ')') {
        const char *s = *p;
        while (**p >= 'A' && **p <= 'Z')
            (*p)++;
        size_t len = (size_t)(*p - s);
        if (!len || **p != '[') {
            *ok = false;
            break;
        }
        char *key = (char *)malloc(len + 1);
        memcpy(key, s, len);
        key[len] = 0;
        size_t k = 0;
        while (k < t->property_count && strcmp(t->properties[k].key, key))
            k++;
        if (k == t->property_count) {
            t->properties =
                (sgf_property *)realloc(t->properties, (k + 1) * sizeof(sgf_property));
            sgf_property v = {key, NULL, 0};
            t->properties[k] = v;
            t->property_count++;
        } else
            free(key);
        sgf_property *prop = t->properties + k;
        while (**p == '[') {
            (*p)++;
            char *value = (char *)malloc(strlen(*p) + 1);
            size_t n = 0;
            while (**p && **p != ']') {
                char c = *(*p)++;
                if (c == '\\') {
                    if (!**p) {
                        *ok = false;
                        break;
                    }
                    c = *(*p)++;
                    if (c == '\n')
                        continue;
                    if (c == '\n') {
                        if (**p == '\n')
                            (*p)++;
                        continue;
                    }
                }
                if (c != '\n' && isspace((unsigned char)c))
                    c = ' ';
                value[n++] = c;
            }
            value[n] = 0;
            if (**p != ']') {
                free(value);
                *ok = false;
                break;
            }
            (*p)++;
            prop->values =
                (char **)realloc(prop->values, (prop->count + 1) * sizeof(char *));
            prop->values[prop->count++] = value;
        }
        if (!*ok)
            break;
    }
    return t;
}
static sgf_tree *sequence(const char **p, bool *ok) {
    if (**p != '(') {
        *ok = false;
        return NULL;
    }
    (*p)++;
    sgf_tree *root = node(p, ok), *tail = root;
    while (*ok && **p == ';') {
        sgf_tree *c = node(p, ok);
        child(tail, c);
        tail = c;
    }
    while (*ok && **p == '(') {
        sgf_tree *c = sequence(p, ok);
        child(tail, c);
    }
    if (**p != ')')
        *ok = false;
    else
        (*p)++;
    return root;
}
sgf_tree *parse(const char *s) {
    bool ok = true;
    sgf_tree *t = sequence(&s, &ok);
    if (!ok || *s) {
        sgf_free(t);
        return NULL;
    }
    return t;
}

