#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    sgf_tree *t = parse("(;A[x[y\\]z][foo]B[bar];C[baz])");
    assert(t && t->property_count == 2 && t->properties[0].count == 2 &&
           !strcmp(t->properties[0].values[0], "x[y]z") && t->child_count == 1);
    sgf_free(t);
    t = parse("(;A[a](;B[b])(;C[c]))");
    assert(t && t->child_count == 2);
    sgf_free(t);
    t = parse("(;A[hello\\\nworld\\\t!])");
    assert(t && !strcmp(t->properties[0].values[0], "helloworld !"));
    sgf_free(t);
    assert(!parse("") && !parse("()") && !parse("(;a[x])") &&
           !parse("(;A[unfinished)"));

    return 0;
}
